-- Stores the source Lottie payloads in Postgres while retaining the Storage URL
-- as the efficient runtime delivery path for the mobile client.
CREATE TABLE IF NOT EXISTS public.exercise_lottie_animations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    exercise_id uuid NOT NULL REFERENCES public.exercises(id) ON DELETE CASCADE,
    figure_variant text NOT NULL CHECK (figure_variant IN ('man', 'woman')),
    lottie_json jsonb NOT NULL,
    storage_url text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (exercise_id, figure_variant)
);

CREATE INDEX IF NOT EXISTS exercise_lottie_animations_exercise_id_idx
    ON public.exercise_lottie_animations (exercise_id);

ALTER TABLE public.exercise_lottie_animations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "authenticated read active exercise Lottie animations"
    ON public.exercise_lottie_animations;

CREATE POLICY "authenticated read active exercise Lottie animations"
    ON public.exercise_lottie_animations
    FOR SELECT TO authenticated
    USING (
        EXISTS (
            SELECT 1
            FROM public.exercises AS exercise
            WHERE exercise.id = exercise_lottie_animations.exercise_id
              AND exercise.is_active = true
        )
    );

